from .objects.mosaiq_select_patient_objects import MosaiqSelectPatient
from interops.libraries.squish_actions import CommonActions
from interops.libraries.desktop import decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME

def __find_open_patient_window() -> bool:
    """Searches for the main Open Patient window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the new_patient_reg.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(MosaiqSelectPatient.ui_Main_Window) is not None else False

def __find_result_cell(searchValue: str) -> object:
    """Searches the Open Patient data grid for the row holding searchValue and returns the
    matching cell within that row.

    -> Hidden function that should not be used outside the context of the open_patient.py file context!

    :param searchValue: Value to locate in the data grid, e.g. an MR number or a last name
    :type searchValue: str
    :raises RuntimeError: This is raised when the Open Patient UI window is not present
    :return: The cell object within the matched row
    :rtype: object
    """
    if not __find_open_patient_window():
        raise RuntimeError('Failed to find Open Patient UI Window')
    entire_row_obj = CommonActions.get_child_object_by_value(CommonActions.get_child_objects(MosaiqSelectPatient.dataGrid_Data_Panel), searchValue)
    return CommonActions.get_child_object_by_value(CommonActions.get_child_objects(entire_row_obj), searchValue)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def typeText_in_patient_last_name(lastName: str) -> None:
    """Locates the main Open Patient window > types a given lastName string into the Filters last name text box.

    :param str lastName: Patients Last Name string to be typed into the Filters last name text box
    """
    if __find_open_patient_window():
        CommonActions.type_in_textfield(MosaiqSelectPatient.filters_Last_Name_Textbox, lastName)

