@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_apply_filters_button() -> None:
    """Locates the main Open Patient window > and clicks the Apply filters button from the top toolbar.
    """
    if __find_open_patient_window():
        CommonActions.left_click_object(MosaiqSelectPatient.topToolbar_Apply_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_search_results() -> 'tuple[object]':
    """Locates the Open Patient UI window and returns a Tuple of all the objects within the search results data grid of the Open Patient UI

    :raises RuntimeError: This is raised when the Open Patient UI window is not present
    :return: A Tuple of ui objects that from the main data grid panel of the Mosaiq Open Patient UI
    :rtype: tuple[object]
    """
    if not __find_open_patient_window():
        raise RuntimeError('Failed to find Open Patient UI Window')
    return CommonActions.get_child_objects(MosaiqSelectPatient.dataGrid_Data_Panel)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_specific_result_using_mr_number(patientMRNumber: str) -> None:
    """Locates the Open Patient UI window > searches the data grid for a patient row object > searches the row for the given patientMRNumber >
    double clicks the MR Number cell

    :param patientMRNumber: String value of the Patient's MR number that will be searched for within the Data Grid Objects
    :type patientMRNumber: str
    :raises RuntimeError: This is raised when the Open Patient UI window is not present
    """
    CommonActions.double_click_object(__find_result_cell(patientMRNumber))

