@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_specific_result_using_mr_number(patientMRNumber: str) -> None:
    """Locates the Open Patient UI window > searches the data grid for a patient row object > searches the row for the
    given patientMRNumber > single clicks the MR Number cell.

    Unlike click_specific_result_using_mr_number(), this only highlights the row: the Select Patient window stays open
    and the chart is NOT opened. Follow with click_select_button() to open the highlighted patient.

    :param patientMRNumber: String value of the Patient's MR number that will be searched for within the Data Grid Objects
    :type patientMRNumber: str
    :raises RuntimeError: This is raised when the Open Patient UI window is not present
    """
