@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_select_button_enabled() -> bool:
    """Locates the main Open Patient window > returns the enabled state of the Select button from the top toolbar.

    The Select button is disabled until a result row is highlighted, so this doubles as a check that a row is
    currently selected.

    :raises RuntimeError: This is raised when the Open Patient UI window is not present
    :return: True when the Select button exists and is enabled, otherwise False
    :rtype: bool
    """
    if not __find_open_patient_window():
        raise RuntimeError('Failed to find Open Patient UI Window')
    # wait_for_object_exists(), NOT find_object(): find_object() falls back to returning the
    # first Edit control in the AUT when its target is missing, and that stand-in reports
    # enabled=True, which would turn a missing Select button into a passing check.
    try:
        select_button = CommonActions.wait_for_object_exists(MosaiqSelectPatient.topToolbar_Select_Button, 5000)
    except Exception:
        return False
    return bool(select_button is not None and getattr(select_button, "enabled", False))

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_select_button() -> None:
    """Locates the main Open Patient window > and clicks the Select button from the top toolbar, opening the chart of
    the currently highlighted patient.

    :raises RuntimeError: This is raised when the Open Patient UI window is not present
    """
    if not __find_open_patient_window():
        raise RuntimeError('Failed to find Open Patient UI Window')
    CommonActions.left_click_object(MosaiqSelectPatient.topToolbar_Select_Button)